INSERT INTO `products` (`id`, `description`, `name`, `price`, `quantity`, `status`, `category_id`, `shop_id`) VALUES (1,'- CPU: Core i7-1250U 3.5Ghz up to 4.7Ghz (12M Cache) 10 Core 12 Threads\n- Ram: 8 GB LPDDR4x-4266 MHz\n- Ổ cứng: 512 GB PCIe® NVMe™ TLC M.2 SSD\n- Màn hình: 13.3\" IPS FHD+ (1920 x 1200), 400 nits, 100% sRGB, multitouch-enabled\n- Đồ hoạ: Intel Iris X Graphics\n- Cổng kết nối: 2 Thunderbolt™ 4 with USB Type-C® 40Gbps signaling rate (USB Power Delivery, DisplayPort™ 1.4, HP Sleep and Charge); 1 USB Type-A 10Gbps signaling rate (HP Sleep and Charge); 1 USB Type-A 10Gbps signaling rate; 1 headphone/','HP Envy X360 13-BF0013DX, core i7-1250U, Ram 8GB, SSD 512GB, 13.3\" FHD cảm ứng gập 360 độ, vỏ nhôm',19690000.00,97,'ACTIVE',3,1),(2,'✨Chào mừng đến với cửa hàng của chúng tôi!✨\n\n📱Các dòng iPhone tương thích:\niPhone 15 Series\niPhone 14 Series\niPhone 13 Series\niPhone 12 Series\niPhone 11 Series\n\n🌿Chất liệu thân thiện với môi trường:\n✅Sản phẩm này sử dụng chất liệu thân thiện với môi trường, vì vậy bạn có thể yên tâm sử dụng và bảo vệ môi trường.\n\n🌟Chất lượng và dịch vụ:\nChất lượng sản phẩm được đảm bảo. Chúng tôi cung cấp dịch vụ nhanh chóng và tuyệt vời. Vui lòng liên hệ với chúng tôi ngay nếu bạn có bất kỳ câu hỏi nào. 📞','Ốp lưng mềm chống sốc họa tiết thiên thạch cho iPhone 15/14/13/12/11 Pro Max',11000.00,2802,'ACTIVE',7,1),(3,'Tính năng điện thoại\nGPS, NFC, Màn hình cảm ứng, chống nước, Wifi\nLoại điện thoại\nĐiện thoại thông minh\nTình trạng\nMới\nBộ xử lý\nApple A16 Bionic\nLoại cáp điện thoại\nUSB-C\nModel điện thoại\nApple iPhone 15 128GB\nĐộ phân giải camera chính\n48MP\nHỗ trợ hệ điều hành\niOS 17\nĐiện thoại di động\n5G\nKích thước (dài x rộng x cao)\n147.6 x 71.6 x 7.80 mm','Apple iPhone 15ProMax Chính hãng VN/A',16890000.00,32,'ACTIVE',2,1),(4,'Chất liệu áo polo cao cấp\nPOLY GAI CÁ SẤU tạo cảm giác mềm mại, đứng dáng, thoáng mát gấp 2,5 lần sợi thường\nVải thun Nano Poly co giãn 4 chiều, không xù lông, không giãn áo\nThoát mát, hút mồ hôi tốt cho mọi hoạt động\nHướng dẫn sử dụng và bảo quản áo\nKhông sử dụng hóa chất tẩy cho áo\nGiặt ở nhiệt độ bình thường, với đồ màu tương tự\nHạn chế máy sấy và ủi ở nhiệt độ thích hợp\nLộn mặt trái khi phơi để tránh phai màu\nLiên hệ shop để được hỗ trợ khi cần.','Áo Thun Polo Nam Thêu Chữ U,Chất Liệu Thấm Hút Mồ Hôi,Cổ Phối Màu',70000.00,1750,'ACTIVE',1,1),(5,'Quần Jean Đen Nam Ống Rộng Dáng Suông  Màu Wash Xám Trầm SMOKE V.1, Quần Jean Nam Chất Vải Dày Dặn Ống Suông Vintage V02\nGió store đang là đơn vị cung cấp các mẫu Jean tốt nhất trên thị trường với giá rẻ so với chất lượng\n- Quần Jean Nam với chất liệu Jeans dày dặn vải chính phẩm. \n- Hỗ trợ khách hàng đổi size miễn phí. và không ưng hoàn tiền ngay.\n- Thương hiệu: NEED US\n- Chất liệu: Chất liệu Jean sử lý giặt mền và xử lý mầu Hạn chế phai mầu tốt hơn so với các đơn vị khác.','Quần Jean Đen Nam Ống Rộng Dáng Suông Màu Wash Xám Trầm SMOKE V.1, Quần Jean Nam Chất Vải Dày Dặn Ống Suông Vintage V02',192000.00,1050,'ACTIVE',1,1),(6,'Instax Mini 12  - Máy chụp ảnh lấy ngay Fujifilm Instax Mini 12\n-Sản phẩm chính hãng mới 100%\n-Nguyên seal \n- Full hộp đầy đủ phụ kiện đi kèm.\n- Bảo hành chính hãng trên toàn quốc \n- Thông tin chi tiết sản phẩm :\nSử dụng film instax mini\nKích thước ảnh in: 62 x 46 mm\nỐng kính FUJINON 60mm (F/12.7) có gương Selfie\nKhoảng cách lấy nét: từ 60 cm đến vô cực (sử dụng chế độ selfie trong 0,3m đến 0,5m)\nPhơi sáng tự động và Flash tự động\nPin: 2 x AA 1.5V, thời lượng chụp: ~100 tấm','Instax Mini 12 - Máy Chụp Ảnh Lấy Ngay Fujifilm Instax Mini 12',2980000.00,49,'ACTIVE',4,1),(7,'Sản phẩm máy ảnh Sony A6000 đen kèm Lens kit 16-50 đã qua sử dụng tình trạng chung như sau:\n • Máy được Shop tuyển chọn kỹ về chức năng lẫn ngoại hình. Máy được bảo quản kỹ trong tủ chống ẩm trong thời gian trưng bày và lưu kho.\n • Sensor đẹp, không trầy, không rễ mốc.\n • Ngoại quan có trầy nhẹ nhưng không đáng kể, tổng quan máy còn rất đẹp (Mỗi đợt sẽ có mỗi máy khác nhau, vui lòng liên hệ để xem ảnh thật của máy).\n • Mọi chức năng máy hoạt động bình thường, không lỗi lầm gì hết. Shop test','Máy Ảnh SONY A6000 + Lens Kit 16-50 OSS',11990000.00,46,'ACTIVE',4,1),(8,'-Chất liệu: Da mềm\n\n-Màu săc: Đơn gián, basic dễ mix đồ \n\n-Kiểu dáng: Thời trang phù hợp với mọi lứa tuổi, thích hợp đi làm, đi học, đi chơi\n\nHàng bên shop là hàng QC full box, tuy nhiên do quá trình vận chuyển có thể hộp sẽ bị móp méo, điều này là không tránh khỏi được nên mong quý khách hiểu và thông cảm.\n\nTùy từng sản phẩm do yếu tố ánh sáng, góc chụp nên màu sắc có thể chênh lệch độ sáng tối 1 chút.','Giày nữ thể thao full trắng đế cao hàng QCCC ELINE',169000.00,70,'ACTIVE',6,2),(10,'Chiều rộng phù hợp\nCó\nXuất xứ\nTrung Quốc\nGiày cao gót\nCao\nLoại Khóa\nKhóa dây\n- Chất liệu : Chất liệu\n\nda mềm\n\n\n\n\n\n\n\n- Màu sắc : đơn giản, basic dễ mix đồ\n\n\n\n\n\n\n\n- Fom quai : quai ôm chân nên đặt đúng size, còn\n\nchân to chiều ngang trừ hao tang size để tránh kích quai nhé.\n\n\n\n\n\n\n\n- Kiểu dáng : thời trang phù hợp với mọi lứa tuổi,\n\nthích hợp đi học đi chơi đi làm.','Giày thể thao nữ HOLA Kiểu dáng trẻ trung năng động',140000.00,80,'ACTIVE',6,2),(14,'Chi Tiết Sản Phẩm\n\nKiểu dáng tối giản nhưng mạnh mẽ, đường nét gọn gàng, khỏe khoắn. Đế cao su ôm trọn bàn chân, tạo cảm giác vững chắc.\n\nĐặc Điểm\n\nPhù hợp với mọi trang phục: Từ jeans bụi bặm đến quần jogger thể thao, quần kaki lịch lãm.\n\nKháng khuẩn và dễ lau chùi: Đế giày chịu ma sát tốt, nhẹ, êm, cân bằng và thoáng khí.\n\nSize Nam: 39-44. Với bàn chân dày, bề ngang to, cộng 1 size so với bình thường.','Giày Sneaker Nam Nữ Unisex Bassic Full 36-44 From Thời Trang Chuẩn Gu Giới Trẻ',166000.00,75,'ACTIVE',6,2),(15,'- Shop cam kết bán sản phẩm Dép đế bánh mì hình gấu chất lượng\n\n\n\n- Tất cả dép banh mì, dép slide của shop đều được bọc kỹ trước khi gửi, nhưng trong quá trình vận chuyển rất có thể hộp sẽ bị móp méo, điều này shop không hề mong muốn và cũng không thể can thiệp được vào công việc vận chuyển của bên shopee, nên mong anh/chị thông cảm. \n\n\n\n\n\n-Tất cả sản phẩm mình đều hỗ trợ cho khách xem hàng, quý khách cứ bảo là shop cho kiểm tra hàng rồi shiper sẽ gọi cho shop.\n\n- Nến anh/chị nhận được Dép bánh','Dép bánh mì vân nhám nam nữ, dép nữ đi trong nhà trơn đế răng cưa cao 4cm',59000.00,525,'ACTIVE',6,2);
